#!/usr/bin/env bash
# GSZ step119 — deliver FULL login credentials on WhatsApp. Adds the credentials
# var to the delivery message and rewrites the whatsapp.credentials template
# (en/ur/ar/ro) to print them. Safe + idempotent; restores on failure.
set -euo pipefail
GSZ=/opt/gsz; TS=$(date +%Y%m%d-%H%M%S); BK="$GSZ/.bak-step119-$TS"; TMP=$(mktemp -d)
F=routes/checkout.js
echo "==> step119: full credentials on WhatsApp"
mkdir -p "$BK/$(dirname "$F")"; cp "$GSZ/$F" "$BK/$F"; echo "    backup: $BK"
restore(){ echo "!! FAILED — restoring"; cp "$BK/$F" "$GSZ/$F"; pm2 restart gsz >/dev/null 2>&1 || true; echo "!! restored."; }
trap 'restore' ERR
echo "" | base64 -d > "$TMP/p.js"
echo "" | base64 -d > "$TMP/m.js"
echo "==> applying"; node "$TMP/p.js" "$GSZ"; node --check "$GSZ/$F"
echo "==> updating credentials template (en/ur/ar/ro)"; ( cd "$GSZ" && NODE_PATH="$GSZ/node_modules" node "$TMP/m.js" )
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz; sleep 2
CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true); [ "$CODE" = "200" ] && echo "    homepage 200: OK" || { echo "    homepage $CODE"; false; }
trap - ERR; rm -rf "$TMP"
echo ""; echo "==> step119 OK ✅  On delivery, the customer's WhatsApp now receives the FULL login details (not just a link), in your enabled languages."
